//! The WHATWG index tables, generated by `turbo-encoding-gen`, and lookups
//! over them that return the index code point for a pointer, or None
//! where the index has none.

mod big5;
mod euc_kr;
mod gb18030;
mod jis0208;
mod jis0212;
mod single_byte;

pub(crate) use single_byte::*;

use turbo_encoding_layers::Encoding;

fn at16(table: &[u16], first: usize, pointer: usize) -> Option<char> {
    let cp = *table.get(pointer.checked_sub(first)?)?;
    if cp == 0 { None } else { char::from_u32(u32::from(cp)) }
}

/// Index jis0208.
pub(crate) fn jis0208(pointer: usize) -> Option<char> {
    at16(&jis0208::JIS0208, jis0208::JIS0208_FIRST, pointer)
}

/// Index jis0212.
pub(crate) fn jis0212(pointer: usize) -> Option<char> {
    at16(&jis0212::JIS0212, jis0212::JIS0212_FIRST, pointer)
}

/// Index EUC-KR.
pub(crate) fn euc_kr(pointer: usize) -> Option<char> {
    at16(&euc_kr::EUC_KR, euc_kr::EUC_KR_FIRST, pointer)
}

/// Index gb18030 (two-byte sequences).
pub(crate) fn gb18030(pointer: usize) -> Option<char> {
    at16(&gb18030::GB18030, 0, pointer)
}

/// Index Big5.
pub(crate) fn big5(pointer: usize) -> Option<char> {
    let cp = *big5::BIG5.get(pointer.checked_sub(big5::BIG5_FIRST)?)?;
    if cp == 0 { None } else { char::from_u32(cp) }
}

/// The index gb18030 ranges code point for a four-byte pointer.
pub(crate) fn gb18030_range(pointer: u32) -> Option<char> {
    if (pointer > 39419 && pointer < 189000) || pointer > 1237575 {
        return None;
    }
    if pointer == 7457 {
        return Some('\u{E7C7}');
    }
    let i = gb18030::GB18030_RANGE_POINTERS.partition_point(|&p| p <= pointer) - 1;
    char::from_u32(gb18030::GB18030_RANGE_CODE_POINTS[i] + pointer - gb18030::GB18030_RANGE_POINTERS[i])
}

/// The table of a single-byte encoding: entry b is the code point of byte
/// 0x80 + b, 0 for none.
pub(crate) fn single_byte_table(e: Encoding) -> Option<&'static [u16; 128]> {
    Some(match e {
        Encoding::Ibm866 => &IBM866,
        Encoding::Iso8859_2 => &ISO_8859_2,
        Encoding::Iso8859_3 => &ISO_8859_3,
        Encoding::Iso8859_4 => &ISO_8859_4,
        Encoding::Iso8859_5 => &ISO_8859_5,
        Encoding::Iso8859_6 => &ISO_8859_6,
        Encoding::Iso8859_7 => &ISO_8859_7,
        Encoding::Iso8859_8 | Encoding::Iso8859_8I => &ISO_8859_8,
        Encoding::Iso8859_10 => &ISO_8859_10,
        Encoding::Iso8859_13 => &ISO_8859_13,
        Encoding::Iso8859_14 => &ISO_8859_14,
        Encoding::Iso8859_15 => &ISO_8859_15,
        Encoding::Iso8859_16 => &ISO_8859_16,
        Encoding::Koi8R => &KOI8_R,
        Encoding::Koi8U => &KOI8_U,
        Encoding::Macintosh => &MACINTOSH,
        Encoding::Windows874 => &WINDOWS_874,
        Encoding::Windows1250 => &WINDOWS_1250,
        Encoding::Windows1251 => &WINDOWS_1251,
        Encoding::Windows1252 => &WINDOWS_1252,
        Encoding::Windows1253 => &WINDOWS_1253,
        Encoding::Windows1254 => &WINDOWS_1254,
        Encoding::Windows1255 => &WINDOWS_1255,
        Encoding::Windows1256 => &WINDOWS_1256,
        Encoding::Windows1257 => &WINDOWS_1257,
        Encoding::Windows1258 => &WINDOWS_1258,
        Encoding::XMacCyrillic => &X_MAC_CYRILLIC,
        _ => return None,
    })
}
